import React, { useState, useEffect } from 'react';
import { Language } from './types';
import { contentData } from './data/content';
import Header from './components/Header';
import Hero from './components/Hero';
import Services from './components/Services';
import PriceList from './components/PriceList';
import Gallery from './components/Gallery';
import Advantages from './components/Advantages';
import FAQ from './components/FAQ';
import Footer from './components/Footer';
import CookieConsent from './components/CookieConsent';
import SchemaMarkup from './components/SchemaMarkup';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('lv');

  // SEO & Meta updates
  useEffect(() => {
    const data = contentData[lang];
    document.title = data.meta.title;

    // Meta Description
    let metaDescription = document.querySelector('meta[name="description"]');
    if (!metaDescription) {
      metaDescription = document.createElement('meta');
      metaDescription.setAttribute('name', 'description');
      document.head.appendChild(metaDescription);
    }
    metaDescription.setAttribute('content', data.meta.description);

    // Meta Keywords
    let metaKeywords = document.querySelector('meta[name="keywords"]');
    if (!metaKeywords) {
      metaKeywords = document.createElement('meta');
      metaKeywords.setAttribute('name', 'keywords');
      document.head.appendChild(metaKeywords);
    }
    metaKeywords.setAttribute('content', data.meta.keywords);

    // Lang attribute
    document.documentElement.lang = lang;

    // Hreflang Tags
    const languages: Language[] = ['lv', 'ru', 'en'];
    languages.forEach(l => {
      let link = document.querySelector(`link[hreflang="${l}"]`);
      if (!link) {
        link = document.createElement('link');
        link.setAttribute('rel', 'alternate');
        link.setAttribute('hreflang', l);
        document.head.appendChild(link);
      }
      // Assuming a single-page URL structure with lang params or just different content states
      link.setAttribute('href', `${window.location.origin}${window.location.pathname}?lang=${l}`);
    });

  }, [lang]);

  const currentContent = contentData[lang];

  return (
    <div className="min-h-screen bg-stone-50 selection:bg-rose-200">
      <SchemaMarkup content={currentContent} lang={lang} />
      <Header lang={lang} setLang={setLang} content={currentContent} />
      <main>
        <Hero content={currentContent} />
        <Services content={currentContent} />
        <PriceList content={currentContent} />
        <Gallery content={currentContent} />
        <Advantages content={currentContent} />
        <FAQ content={currentContent} />
      </main>
      <Footer content={currentContent} />
      <CookieConsent content={currentContent} />
    </div>
  );
};

