    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: content.nav.home, action: () => setView('home') },
    { name: content.nav.services, action: () => { setView('home'); setTimeout(() => document.getElementById('services')?.scrollIntoView({behavior: 'smooth'}), 100); } },
    { name: content.nav.prices, action: () => { setView('home'); setTimeout(() => document.getElementById('prices')?.scrollIntoView({behavior: 'smooth'}), 100); } },
    { name: content.nav.faq, action: () => setView('faq') },
    { name: content.nav.contacts, action: () => document.getElementById('contacts')?.scrollIntoView({behavior: 'smooth'}) },
  ];

  return (
    <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${scrolled || view === 'faq' ? 'bg-white/95 backdrop-blur-md shadow-md py-3' : 'bg-transparent py-5'}`}>
      <div className="container mx-auto px-4 flex justify-between items-center">
        {/* Logo */}
        <button onClick={() => setView('home')} className={`text-3xl font-serif font-bold tracking-wide transition-colors ${scrolled || view === 'faq' ? 'text-primary' : 'text-white'}`}>
          Salons <span className={scrolled || view === 'faq' ? 'text-stone-800' : 'text-stone-200'}>Aneri</span>
        </button>

        {/* Desktop Nav */}
        <nav className={`hidden lg:flex space-x-8 items-center px-6 py-2 rounded-full border transition-all ${scrolled || view === 'faq' ? 'border-stone-200 bg-stone-50/50' : 'border-white/20 bg-white/10 backdrop-blur-sm'}`}>
          {navLinks.map((link) => (
            <button
              key={link.name}
              onClick={() => { link.action(); setIsOpen(false); }}
              className={`font-medium text-xs uppercase tracking-widest hover:text-primary transition-colors ${scrolled || view === 'faq' ? 'text-stone-600' : 'text-white'}`}
            >
              {link.name}
            </button>
          ))}
        </nav>

        {/* Desktop Actions */}
        <div className="hidden lg:flex items-center space-x-6">
          <div className="flex flex-col items-end">
             <a href="tel:+37127580047" className={`flex items-center gap-2 font-bold text-lg transition-colors hover:text-primary ${scrolled || view === 'faq' ? 'text-stone-800' : 'text-white'}`}>
                <Phone size={18} className="text-primary" />
                +371 27580047
             </a>
             <div className={`flex gap-3 text-xs font-bold uppercase ${scrolled || view === 'faq' ? 'text-stone-400' : 'text-white/60'}`}>
                {(['lv', 'ru', 'en'] as Language[]).map((l) => (
                  <button key={l} onClick={() => setLang(l)} className={`hover:text-primary ${lang === l ? 'text-primary underline' : ''}`}>
                    {l}
                  </button>
                ))}
             </div>
          </div>
          <a href="tel:+37127580047" className="bg-primary text-white px-6 py-3 rounded-full text-sm font-bold hover:bg-rose-800 transition shadow-lg">
             {content.nav.bookBtn}
          </a>
        </div>

        {/* Mobile Burger */}
        <div className="lg:hidden flex items-center space-x-4">
          <button onClick={() => setIsOpen(!isOpen)} className={scrolled || view === 'faq' ? 'text-stone-800' : 'text-white'}>
            {isOpen ? <X size={32} /> : <Menu size={32} />}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="lg:hidden bg-white fixed inset-0 z-50 flex flex-col pt-24 px-6 space-y-6 overflow-y-auto">
          <button onClick={() => setIsOpen(false)} className="absolute top-6 right-6 text-stone-800">
             <X size={32} />
