          <div className="flex justify-center gap-6 mb-8">
             {(['lv', 'ru', 'en'] as Language[]).map((l) => (
                <button key={l} onClick={() => setLang(l)} className={`text-xl font-bold uppercase ${lang === l ? 'text-primary underline' : 'text-stone-400'}`}>
                  {l}
                </button>
             ))}
          </div>
          <nav className="flex flex-col space-y-6 text-center">
            {navLinks.map((link) => (
              <button
                key={link.name}
                onClick={() => { link.action(); setIsOpen(false); }}
