              >
                {link.name}
              </button>
            ))}
            <div className="pt-6">
                <a href="tel:+37127580047" className="w-full bg-primary text-white px-5 py-4 rounded-xl text-center font-bold shadow-md text-xl flex items-center justify-center gap-3">
                    <Phone /> +371 27580047
                </a>
            </div>
          </nav>
        </div>
      )}
