import React, { useState, useEffect } from 'react';
import { Language, View } from './types';
import { contentData } from './data/content';
import Header from './components/Header';
import Hero from './components/Hero';
import Services from './components/Services';
import PriceList from './components/PriceList';
import Gallery from './components/Gallery';
import Advantages from './components/Advantages';
import FAQPage from './components/FAQPage';
import TermsPage from './components/TermsPage';
import Footer from './components/Footer';
import CookieConsent from './components/CookieConsent';
import SchemaMarkup from './components/SchemaMarkup';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('lv');
  const [view, setView] = useState<View>('home');

  useEffect(() => {
    const data = contentData[lang];
    let pageTitle = data.meta.title;
    if (view === 'faq') pageTitle = `${data.faq.title} | Salons Aneri`;
    if (view === 'terms') pageTitle = `${data.terms.title} | Salons Aneri`;
    if (view === 'privacy') pageTitle = `${data.privacy.title} | Salons Aneri`;

    document.title = pageTitle;
    document.documentElement.lang = lang;
    window.scrollTo(0, 0);

  }, [lang, view]);

  const currentContent = contentData[lang];

  return (
    <div className="min-h-screen bg-stone-50 selection:bg-rose-200">
      <SchemaMarkup content={currentContent} lang={lang} />
      <Header 
        lang={lang} 
        setLang={setLang} 
        content={currentContent} 
        view={view}
        setView={setView}
      />

      <main>
        {view === 'home' && (
          <>
            <Hero content={currentContent} />
            <Services content={currentContent} />
            <PriceList content={currentContent} />
            <Gallery content={currentContent} />
            <Advantages content={currentContent} />
          </>
        )}
        {view === 'faq' && <FAQPage content={currentContent} setView={setView} />}
        {view === 'terms' && <TermsPage title={currentContent.terms.title} content={currentContent.terms.content} setView={setView} homeLabel={currentContent.nav.home} />}
        {view === 'privacy' && <TermsPage title={currentContent.privacy.title} content={currentContent.privacy.content} setView={setView} homeLabel={currentContent.nav.home} />}
      </main>

      <Footer content={currentContent} setView={setView} />
      <CookieConsent content={currentContent} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Language, Content, View } from '../types';
import { Menu, X, Phone } from 'lucide-react';

interface HeaderProps {
  lang: Language;
  setLang: (lang: Language) => void;
  content: Content;
  view: View;
  setView: (view: View) => void;
}

const Header: React.FC<HeaderProps> = ({ lang, setLang, content, view, setView }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 30);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: content.nav.home, action: () => setView('home') },
    { name: content.nav.services, action: () => { setView('home'); setTimeout(() => document.getElementById('services')?.scrollIntoView({behavior: 'smooth'}), 50); } },
    { name: content.nav.prices, action: () => { setView('home'); setTimeout(() => document.getElementById('prices')?.scrollIntoView({behavior: 'smooth'}), 50); } },
    { name: content.nav.faq, action: () => setView('faq') },
    { name: content.nav.contacts, action: () => document.getElementById('contacts')?.scrollIntoView({behavior: 'smooth'}) },
  ];

  const isLight = !scrolled && view === 'home';

  return (
    <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${!isLight ? 'bg-white/90 backdrop-blur-xl border-b border-stone-100 py-3 shadow-sm' : 'bg-transparent py-6'}`}>
      <div className="container mx-auto px-4 flex justify-between items-center">
        {/* Logo */}
        <button onClick={() => setView('home')} className="group flex flex-col items-start leading-none">
          <span className={`text-3xl md:text-4xl font-serif font-bold transition-colors ${!isLight ? 'text-primary' : 'text-white'}`}>
            Salons <span className={!isLight ? 'text-stone-900' : 'text-stone-100'}>Aneri</span>
          </span>
        </button>

        {/* Desktop Nav */}
        <nav className="hidden lg:flex items-center space-x-10">
          {navLinks.map((link) => (
            <button
              key={link.name}
              onClick={() => { link.action(); setIsOpen(false); }}
              className={`text-[11px] uppercase tracking-[0.2em] font-medium hover:text-primary transition-all ${!isLight ? 'text-stone-600' : 'text-white/80 hover:text-white'}`}
            >
              {link.name}
            </button>
          ))}
        </nav>

        {/* Contact & Language */}
        <div className="hidden lg:flex items-center space-x-10">
          <div className="flex flex-col items-end">
            <a href="tel:+37127580047" className={`flex items-center gap-2 text-xl font-serif font-bold transition-all hover:scale-105 ${!isLight ? 'text-stone-900' : 'text-white'}`}>
              <Phone size={16} className="text-primary" />
              +371 27580047
            </a>
            <div className="flex gap-4 mt-1">
              {(['lv', 'ru', 'en'] as Language[]).map((l) => (
                <button 
                  key={l} 
                  onClick={() => setLang(l)} 
                  className={`text-[10px] font-bold uppercase tracking-widest transition-opacity hover:opacity-100 ${lang === l ? 'text-primary' : !isLight ? 'text-stone-400 opacity-60' : 'text-white/40 opacity-40'}`}
                >
                  {l}
                </button>
              ))}
            </div>
          </div>
          <a href="tel:+37127580047" className="bg-primary text-white px-8 py-3 rounded-full text-[12px] font-bold uppercase tracking-wider hover:bg-stone-900 transition-colors shadow-lg">
            {content.nav.bookBtn}
          </a>
