import React, { useState, useEffect } from 'react';
import { Language, Content, View } from '../types';
import { Menu, X, Phone } from 'lucide-react';

interface HeaderProps {
  lang: Language;
  setLang: (lang: Language) => void;
  content: Content;
  view: View;
  setView: (view: View) => void;
}

const Header: React.FC<HeaderProps> = ({ lang, setLang, content, view, setView }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 30);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: content.nav.home, action: () => setView('home') },
    { name: content.nav.services, action: () => { setView('home'); setTimeout(() => document.getElementById('services')?.scrollIntoView({behavior: 'smooth'}), 50); } },
    { name: content.nav.prices, action: () => setView('prices') },
    { name: content.nav.faq, action: () => setView('faq') },
    { name: content.nav.contacts, action: () => { setView('home'); setTimeout(() => document.getElementById('contacts')?.scrollIntoView({behavior: 'smooth'}), 50); } },
  ];

  const isLight = !scrolled && view === 'home';

  return (
    <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${!isLight ? 'bg-white/95 backdrop-blur-xl border-b border-stone-100 py-3 shadow-sm' : 'bg-transparent py-6'}`}>
      <div className="container mx-auto px-4 flex justify-between items-center">
        {/* Logo */}
        <button 
          onClick={() => setView('home')} 
          className="group flex flex-col items-start leading-none focus:outline-none"
          aria-label="Salons Aneri Home"
        >
          <span className={`text-3xl md:text-4xl font-serif font-bold transition-colors ${!isLight ? 'text-primary' : 'text-white'}`}>
            Salons <span className={!isLight ? 'text-stone-900' : 'text-stone-100'}>Aneri</span>
          </span>
        </button>

        {/* Desktop Nav */}
        <nav className="hidden lg:flex items-center space-x-10" aria-label="Main Navigation">
          {navLinks.map((link) => (
            <button
              key={link.name}
              onClick={() => { link.action(); setIsOpen(false); }}
              className={`text-[11px] uppercase tracking-[0.2em] font-semibold hover:text-primary transition-all focus:outline-none ${!isLight ? 'text-stone-600' : 'text-white/90 hover:text-white'}`}
            >
              {link.name}
            </button>
          ))}
        </nav>

        {/* Contact & Language */}
        <div className="hidden lg:flex items-center space-x-10">
          <div className="flex flex-col items-end">
            <a 
              href="tel:+37127580047" 
              className={`flex items-center gap-2 text-xl font-sans font-bold tracking-tight transition-all hover:text-primary ${!isLight ? 'text-stone-900' : 'text-white'}`}
              aria-label="Call Salons Aneri"
            >
              <Phone size={18} className="text-primary" />
              <span className="tabular-nums font-sans tracking-wider">+371 27580047</span>
            </a>
            <div className="flex gap-4 mt-1">
              {(['lv', 'ru', 'en'] as Language[]).map((l) => (
                <button 
                  key={l} 
                  onClick={() => setLang(l)} 
                  className={`text-[10px] font-bold uppercase tracking-widest transition-opacity hover:opacity-100 focus:outline-none ${lang === l ? 'text-primary' : !isLight ? 'text-stone-400 opacity-60' : 'text-white/40 opacity-40'}`}
                  aria-label={`Switch language to ${l}`}
                >
                  {l}
                </button>
              ))}
            </div>
          </div>
          <a 
            href="tel:+37127580047" 
            className="bg-primary text-white px-8 py-3 rounded-full text-[12px] font-bold uppercase tracking-wider hover:bg-stone-900 transition-colors shadow-lg focus:outline-none"
            aria-label="Book an appointment"
          >
            {content.nav.bookBtn}
          </a>
        </div>

        {/* Mobile Burger */}
        <button 
          onClick={() => setIsOpen(!isOpen)} 
          className={`lg:hidden transition-colors focus:outline-none ${!isLight ? 'text-stone-900' : 'text-white'}`}
          aria-label="Toggle Menu"
        >
          {isOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="lg:hidden fixed inset-0 bg-white z-[60] flex flex-col pt-24 px-8 space-y-8 animate-in fade-in slide-in-from-right duration-300">
          <button onClick={() => setIsOpen(false)} className="absolute top-6 right-6 text-stone-900" aria-label="Close Menu">
            <X size={32} />
          </button>
          <nav className="flex flex-col space-y-8">
            {navLinks.map((link) => (
              <button
                key={link.name}
                onClick={() => { link.action(); setIsOpen(false); }}
                className="text-3xl font-serif font-bold text-stone-900 text-left border-b border-stone-50 pb-4"
              >
                {link.name}
              </button>
            ))}
          </nav>
          <div className="pt-4 space-y-6">
            <a href="tel:+37127580047" className="flex items-center justify-center gap-3 w-full bg-primary text-white py-5 rounded-2xl font-sans font-bold text-2xl shadow-xl">
              <Phone size={24} /> <span className="tabular-nums">+371 27580047</span>
            </a>
            <div className="flex justify-center gap-8">
               {(['lv', 'ru', 'en'] as Language[]).map((l) => (
                <button key={l} onClick={() => { setLang(l); setIsOpen(false); }} className={`text-lg font-bold uppercase tracking-widest ${lang === l ? 'text-primary' : 'text-stone-300'}`}>
                  {l}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}
    </header>
  );
};

