import React, { useState, useEffect } from 'react';
import { Language, Content, View } from '../types';
import { Menu, X, Phone } from 'lucide-react';

interface HeaderProps {
  lang: Language;
  setLang: (lang: Language) => void;
  content: Content;
  view: View;
  setView: (view: View) => void;
}

const Header: React.FC<HeaderProps> = ({ lang, setLang, content, view, setView }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 30);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: content.nav.home, action: () => setView('home') },
    { name: content.nav.services, action: () => { setView('home'); setTimeout(() => document.getElementById('services')?.scrollIntoView({behavior: 'smooth'}), 50); } },
    { name: content.nav.prices, action: () => setView('prices') },
    { name: content.nav.faq, action: () => setView('faq') },
    { name: content.nav.contacts, action: () => { setView('home'); setTimeout(() => document.getElementById('contacts')?.scrollIntoView({behavior: 'smooth'}), 50); } },
  ];

  const isLight = !scrolled && view === 'home';

  return (
    <header className={`fixed top-0 left-0 right-0 z-[100] transition-all duration-500 ${!isLight ? 'bg-white/95 backdrop-blur-xl border-b border-stone-100 py-3 shadow-sm' : 'bg-transparent py-6'}`}>
      <div className="container mx-auto px-4 flex justify-between items-center">
        {/* Logo */}
        <button 
          onClick={() => setView('home')} 
          className="group flex flex-col items-start leading-none focus:outline-none"
          aria-label="Salons Aneri Home"
        >
          <span className={`text-3xl md:text-5xl font-serif font-bold transition-colors ${!isLight ? 'text-primary' : 'text-white'}`}>
            Salons <span className={!isLight ? 'text-stone-900' : 'text-stone-100'}>Aneri</span>
          </span>
        </button>

        {/* Desktop Nav */}
        <nav className="hidden lg:flex items-center space-x-12" aria-label="Main Navigation">
          {navLinks.map((link) => (
            <button
              key={link.name}
              onClick={() => { link.action(); setIsOpen(false); }}
              className={`text-[12px] uppercase tracking-[0.25em] font-bold hover:text-primary transition-all focus:outline-none ${!isLight ? 'text-stone-600' : 'text-white/90 hover:text-white'}`}
            >
              {link.name}
            </button>
          ))}
        </nav>

        {/* Contact & Language */}
        <div className="hidden lg:flex items-center space-x-12">
          <div className="flex flex-col items-end">
            <a 
              href="tel:+37127580047" 
              className={`flex items-center gap-3 text-2xl font-sans font-bold tracking-tight transition-all hover:text-primary ${!isLight ? 'text-stone-900' : 'text-white'}`}
              aria-label="Call Salons Aneri"
            >
              <Phone size={20} className="text-primary" />
              <span className="tabular-nums font-sans tracking-widest">+371 27580047</span>
            </a>
            <div className="flex gap-5 mt-2">
              {(['lv', 'ru', 'en'] as Language[]).map((l) => (
                <button 
                  key={l} 
                  onClick={() => setLang(l)} 
                  className={`text-[11px] font-black uppercase tracking-[0.2em] transition-all hover:scale-110 focus:outline-none ${lang === l ? 'text-primary' : !isLight ? 'text-stone-400' : 'text-white/50'}`}
                  aria-label={`Switch language to ${l}`}
                >
                  {l}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Mobile Burger */}
        <button 
          onClick={() => setIsOpen(!isOpen)} 
          className={`lg:hidden transition-colors focus:outline-none ${!isLight ? 'text-stone-900' : 'text-white'}`}
          aria-label="Toggle Menu"
        >
          {isOpen ? <X size={35} /> : <Menu size={35} />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="lg:hidden fixed inset-0 bg-stone-50 z-[110] flex flex-col pt-32 px-10 space-y-10 animate-in fade-in slide-in-from-right duration-500">
          <button onClick={() => setIsOpen(false)} className="absolute top-8 right-8 text-stone-900" aria-label="Close Menu">
            <X size={45} />
          </button>
          <nav className="flex flex-col space-y-10">
            {navLinks.map((link) => (
              <button
                key={link.name}
                onClick={() => { link.action(); setIsOpen(false); }}
                className="text-4xl font-serif font-bold text-stone-900 text-left border-b border-stone-200 pb-6"
              >
                {link.name}
              </button>
            ))}
