// Helper component to render an image and hide it if it fails to load
const SmartImage = ({ src, alt }: { src: string; alt: string }) => {
  const [hasError, setHasError] = useState(false);
  const [loaded, setLoaded] = useState(false);

  if (hasError) return null;

  return (
    <div className={`relative rounded-xl overflow-hidden aspect-square bg-stone-100 shadow-md ${!loaded ? 'animate-pulse' : ''}`}>
      <img
        src={src}
        alt={alt}
        className={`w-full h-full object-cover transition-all duration-500 hover:scale-105 ${loaded ? 'opacity-100' : 'opacity-0'}`}
        onLoad={() => setLoaded(true)}
        onError={() => setHasError(true)}
      />
    </div>
  );
};

const GalleryPage: React.FC<GalleryPageProps> = ({ content, setView }) => {
  const [activeCategory, setActiveCategory] = useState<string | null>(null);

  const activeCategoryData = content.gallery.categories.find(c => c.id === activeCategory);

  return (
    <section className="pt-32 pb-24 min-h-screen bg-stone-50">
      <div className="container mx-auto px-4 max-w-6xl">
        <div className="flex items-center justify-between mb-12">
            <button 
              onClick={() => activeCategory ? setActiveCategory(null) : setView('home')} 
              className="flex items-center gap-2 text-primary text-xs font-bold uppercase tracking-widest hover:-translate-x-1 transition-transform"
            >
              <ArrowLeft size={16} /> {activeCategory ? content.gallery.title : content.nav.home}
            </button>
        </div>

        {!activeCategory ? (
          // Category List View
          <>
             <div className="text-center mb-20">
                <h1 className="text-5xl md:text-8xl font-serif font-bold text-stone-900 mb-6 tracking-tight">{content.gallery.title}</h1>
                <p className="text-xl text-stone-500 max-w-2xl mx-auto font-light leading-relaxed italic">{content.gallery.description}</p>
            </div>

            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
              {content.gallery.categories.map((category) => (
                <button 
                  key={category.id}
                  onClick={() => setActiveCategory(category.id)}
                  className="group relative h-80 w-full overflow-hidden rounded-[2rem] shadow-lg text-left"
                >
                   {/* Background Image with Fallback */}
                  <img 
                    src={category.image} 
                    alt={category.title}
                    className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
