                  <div className="absolute inset-0 bg-stone-900/40 group-hover:bg-stone-900/30 transition-colors" />

                  <div className="absolute bottom-0 left-0 p-8 w-full">
                    <div className="flex items-center gap-3 text-white/80 mb-2">
                       <FolderOpen size={18} />
                       <span className="text-xs font-bold uppercase tracking-widest">Kategorija</span>
                    </div>
                    <h3 className="text-3xl font-serif font-bold text-white group-hover:text-primary transition-colors">{category.title}</h3>
                  </div>
                </button>
              ))}
            </div>
          </>
        ) : (
          // Detail View (Images)
          <div className="animate-in fade-in slide-in-from-bottom-8 duration-500">
             <div className="text-center mb-16">
                <h2 className="text-4xl md:text-6xl font-serif font-bold text-stone-900 mb-4">{activeCategoryData?.title}</h2>
                <div className="w-24 h-1 bg-primary mx-auto rounded-full" />
