import React from 'react';
import { Content, View } from '../types';
import { ArrowRight, Sparkles } from 'lucide-react';

interface ServicesProps {
  content: Content;
  setView?: (view: View) => void;
}

const Services: React.FC<ServicesProps> = ({ content, setView }) => {
  const { services } = content;

  // Function to handle navigation to the specific price section
  const handleServiceClick = (id: string) => {
    if (setView) {
      setView('prices');
      // Small delay to allow the view to change before scrolling
      setTimeout(() => {
        const element = document.getElementById(id);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      }, 100);
    }
  };

  return (
    <section id="services" className="py-24 bg-stone-50">
      <div className="container mx-auto px-4">
        <div className="text-center mb-20">
          <h2 className="text-4xl md:text-6xl font-serif font-bold text-stone-800 mb-6">{services.title}</h2>
          <div className="w-24 h-1 bg-primary mx-auto rounded-full"></div>
        </div>

        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8 max-w-7xl mx-auto">
          {services.items.map((item, index) => (
            <button
              key={item.id}
              onClick={() => handleServiceClick(item.id)}
              className="group text-left bg-white p-10 rounded-[2rem] border border-stone-100 shadow-sm hover:shadow-xl hover:border-primary/20 transition-all duration-300 transform hover:-translate-y-1"
            >
              <div className="flex justify-between items-start mb-6">
                <div className="w-12 h-12 rounded-full bg-stone-50 text-primary flex items-center justify-center group-hover:bg-primary group-hover:text-white transition-colors duration-300">
                  <Sparkles size={20} strokeWidth={1.5} />
                </div>
                <div className="text-stone-300 group-hover:text-primary transition-colors duration-300">
                  <ArrowRight size={24} className="transform -rotate-45 group-hover:rotate-0 transition-transform duration-300" />
                </div>
              </div>

              <h3 className="text-2xl font-serif font-bold text-stone-800 mb-3 group-hover:text-primary transition-colors">
                {item.title}
              </h3>

              <p className="text-stone-500 leading-relaxed font-light text-sm">
                {item.description}
              </p>
            </button>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Services;

import React, { useState, useEffect } from 'react';
import { Language, View } from './types';
import { contentData } from './data/content';
import Header from './components/Header';
import Hero from './components/Hero';
import Services from './components/Services';
import PricePage from './components/PricePage';
import GalleryPage from './components/GalleryPage';
import Advantages from './components/Advantages';
import FAQPage from './components/FAQPage';
import TermsPage from './components/TermsPage';
import Footer from './components/Footer';
import CookieConsent from './components/CookieConsent';
import SchemaMarkup from './components/SchemaMarkup';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('lv');
  const [view, setView] = useState<View>('home');

  useEffect(() => {
    const data = contentData[lang];
    let pageTitle = data.meta.title;
    if (view === 'faq') pageTitle = `${data.faq.title} | Salons Aneri`;
    if (view === 'prices') pageTitle = `${data.prices.title} | Salons Aneri`;
    if (view === 'gallery') pageTitle = `${data.gallery.title} | Salons Aneri`;
    if (view === 'terms') pageTitle = `${data.terms.title} | Salons Aneri`;
    if (view === 'privacy') pageTitle = `${data.privacy.title} | Salons Aneri`;

    document.title = pageTitle;
    document.documentElement.lang = lang;

    let metaDesc = document.querySelector('meta[name="description"]');
    if (metaDesc) metaDesc.setAttribute('content', data.meta.description);

    let canonical = document.querySelector('link[rel="canonical"]');
    if (!canonical) {
      canonical = document.createElement('link');
      canonical.setAttribute('rel', 'canonical');
      document.head.appendChild(canonical);
    }
    canonical.setAttribute('href', window.location.origin + (view === 'home' ? '' : `/${view}`));

    window.scrollTo(0, 0);
  }, [lang, view]);

  const currentContent = contentData[lang];

  return (
    <div className="min-h-screen bg-stone-50 selection:bg-rose-200">
      <SchemaMarkup content={currentContent} lang={lang} />
      <Header 
        lang={lang} 
        setLang={setLang} 
        content={currentContent} 
        view={view}
        setView={setView}
      />

      <main id="main-content">
        {view === 'home' && (
          <>
            <Hero content={currentContent} />
            <Services content={currentContent} setView={setView} />
            <Advantages content={currentContent} />
          </>
        )}
        {view === 'prices' && <PricePage content={currentContent} setView={setView} />}
        {view === 'gallery' && <GalleryPage content={currentContent} setView={setView} />}
        {view === 'faq' && <FAQPage content={currentContent} setView={setView} />}
        {view === 'terms' && <TermsPage title={currentContent.terms.title} content={currentContent.terms.content} setView={setView} homeLabel={currentContent.nav.home} />}
        {view === 'privacy' && <TermsPage title={currentContent.privacy.title} content={currentContent.privacy.content} setView={setView} homeLabel={currentContent.nav.home} />}
      </main>

      <Footer content={currentContent} setView={setView} />
      <CookieConsent content={currentContent} />
    </div>
  );
};

export default App;

