import React, { useState, useEffect } from 'react';
import { Language, Content, View } from '../types';
import { Menu, X, Phone } from 'lucide-react';

interface HeaderProps {
  lang: Language;
  setLang: (lang: Language) => void;
  content: Content;
  view: View;
  setView: (view: View) => void;
}

const Header: React.FC<HeaderProps> = ({ lang, setLang, content, view, setView }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 30);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Updated navigation handler
  const handleNavigation = (actionType: 'view' | 'scroll' | 'external', target: string) => {
    setIsOpen(false); // Always close mobile menu

    if (actionType === 'external') {
      window.open(target, '_blank', 'noopener,noreferrer');
      return;
    }

    if (actionType === 'scroll') {
      setView('home');
      setTimeout(() => {
        document.getElementById(target)?.scrollIntoView({ behavior: 'smooth' });
      }, 50);
      return;
    }

    if (actionType === 'view') {
      setView(target as View);
    }
  };

  const navLinks = [
    { name: content.nav.home, type: 'view', target: 'home' },
    { name: content.nav.services, type: 'scroll', target: 'services' },
    { name: content.nav.prices, type: 'view', target: 'prices' },
    { name: content.nav.faq, type: 'view', target: 'faq' },
    { name: content.nav.gallery, type: 'external', target: 'https://www.instagram.com/salons_aneri/' }, // Updated to Instagram
    { name: content.nav.contacts, type: 'scroll', target: 'contacts' },
  ];

  const isLight = !scrolled && view === 'home';

  return (
    <header className={`fixed top-0 left-0 right-0 z-[100] transition-all duration-500 ${!isLight ? 'bg-white/95 backdrop-blur-xl border-b border-stone-100 py-3 shadow-sm' : 'bg-transparent py-6'}`}>
      <div className="container mx-auto px-4 flex justify-between items-center">
        {/* Logo */}
        <button 
          onClick={() => handleNavigation('view', 'home')} 
          className="group flex flex-col items-start leading-none focus:outline-none"
          aria-label="Salons Aneri Home"
        >
          <span className={`text-3xl md:text-4xl font-serif font-bold transition-colors ${!isLight ? 'text-primary' : 'text-white'}`}>
            Salons <span className={!isLight ? 'text-stone-900' : 'text-stone-100'}>Aneri</span>
          </span>
        </button>

        {/* Desktop Nav */}
        <nav className="hidden lg:flex items-center space-x-8 xl:space-x-10" aria-label="Main Navigation">
          {navLinks.map((link) => (
            <button
              key={link.name}
              onClick={() => handleNavigation(link.type as any, link.target)}
              className={`text-[11px] uppercase tracking-[0.2em] font-semibold hover:text-primary transition-all focus:outline-none ${!isLight ? 'text-stone-600' : 'text-white/90 hover:text-white'}`}
            >
              {link.name}
            </button>
          ))}
        </nav>

        {/* Contact & Language */}
        <div className="hidden lg:flex items-center space-x-10">
          <div className="flex flex-col items-end">
            <a 
              href="tel:+37127580047" 
              className={`flex items-center gap-2 text-xl font-sans font-bold tracking-tight transition-all hover:text-primary ${!isLight ? 'text-stone-900' : 'text-white'}`}
              aria-label="Call Salons Aneri"
            >
              <Phone size={18} className="text-primary" />
              <span className="tabular-nums font-sans tracking-wider">+371 27580047</span>
            </a>
            <div className="flex gap-4 mt-1">
              {(['lv', 'ru', 'en'] as Language[]).map((l) => (
                <button 
                  key={l} 
                  onClick={() => setLang(l)} 
                  className={`text-[10px] font-bold uppercase tracking-widest transition-opacity hover:opacity-100 focus:outline-none ${lang === l ? 'text-primary' : !isLight ? 'text-stone-400 opacity-60' : 'text-white/40 opacity-40'}`}
                  aria-label={`Switch language to ${l}`}
                >
                  {l}
                </button>
              ))}
            </div>
          </div>
          <a 
            href="tel:+37127580047" 
            className="bg-primary text-white px-8 py-3 rounded-full text-[12px] font-bold uppercase tracking-wider hover:bg-stone-900 transition-colors shadow-lg focus:outline-none"
            aria-label="Book an appointment"
          >
            {content.nav.bookBtn}
          </a>
        </div>

        {/* Mobile Burger */}
        <button 
          onClick={() => setIsOpen(!isOpen)} 
          className={`lg:hidden transition-colors focus:outline-none relative z-[110] ${isOpen ? 'text-stone-900' : (!isLight ? 'text-stone-900' : 'text-white')}`}
          aria-label="Toggle Menu"
        >
          {isOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Mobile Menu - Fixed transparency and overlap issues */}
      {isOpen && (
        <div className="lg:hidden fixed inset-0 bg-white z-[105] flex flex-col pt-24 px-8 space-y-8 animate-in fade-in slide-in-from-right duration-300 overflow-y-auto">
          <nav className="flex flex-col space-y-6">
            {navLinks.map((link) => (
              <button
                key={link.name}
                onClick={() => handleNavigation(link.type as any, link.target)}
                className="text-2xl font-serif font-bold text-stone-900 text-left border-b border-stone-100 pb-4 active:text-primary"
              >
                {link.name}
              </button>
            ))}
          </nav>
          <div className="pt-4 space-y-6 pb-10">
            <a href="tel:+37127580047" className="flex items-center justify-center gap-3 w-full bg-primary text-white py-5 rounded-2xl font-sans font-bold text-2xl shadow-xl">
              <Phone size={24} /> <span className="tabular-nums">+371 27580047</span>
            </a>
            <div className="flex justify-center gap-8">
               {(['lv', 'ru', 'en'] as Language[]).map((l) => (
                <button key={l} onClick={() => { setLang(l); setIsOpen(false); }} className={`text-lg font-bold uppercase tracking-widest ${lang === l ? 'text-primary' : 'text-stone-300'}`}>
                  {l}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}
    </header>
  );
};

export default Header;

import React from 'react';
import { Content, View } from '../types';
import { ArrowRight, Sparkles } from 'lucide-react';

interface ServicesProps {
  content: Content;
  setView?: (view: View) => void;
}

const Services: React.FC<ServicesProps> = ({ content, setView }) => {
  const { services } = content;

  // Function to handle navigation to the specific price section
  const handleServiceClick = (id: string) => {
    if (setView) {
      setView('prices');
      // Small delay to allow the view to change before scrolling
      setTimeout(() => {
        const element = document.getElementById(id);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      }, 100);
    }
  };

  return (
    <section id="services" className="py-16 bg-stone-50">
      <div className="container mx-auto px-4">
        <div className="text-center mb-10">
          <h2 className="text-4xl md:text-6xl font-serif font-bold text-stone-800 mb-4">{services.title}</h2>
          <div className="w-24 h-1 bg-primary mx-auto rounded-full"></div>
        </div>

        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-5 max-w-7xl mx-auto">
          {services.items.map((item, index) => (
            <button
              key={item.id}
              onClick={() => handleServiceClick(item.id)}
              className="group text-left bg-white p-6 rounded-[1.5rem] border border-stone-100 shadow-sm hover:shadow-xl hover:border-primary/20 transition-all duration-300 transform hover:-translate-y-1"
            >
              <div className="flex justify-between items-start mb-4">
                <div className="w-10 h-10 rounded-full bg-stone-50 text-primary flex items-center justify-center group-hover:bg-primary group-hover:text-white transition-colors duration-300">
                  <Sparkles size={18} strokeWidth={1.5} />
                </div>
                <div className="text-stone-300 group-hover:text-primary transition-colors duration-300">
                  <ArrowRight size={20} className="transform -rotate-45 group-hover:rotate-0 transition-transform duration-300" />
                </div>
              </div>

              <h3 className="text-xl font-serif font-bold text-stone-800 mb-2 group-hover:text-primary transition-colors">
                {item.title}
              </h3>

              <p className="text-stone-500 leading-relaxed font-light text-sm">
                {item.description}
              </p>
            </button>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Services;

import React, { useState, useEffect } from 'react';
import { Language, View } from './types';
import { contentData } from './data/content';
import Header from './components/Header';
import Hero from './components/Hero';
import Services from './components/Services';
import PricePage from './components/PricePage';
// GalleryPage removed as we now link to Instagram
import Advantages from './components/Advantages';
import FAQPage from './components/FAQPage';
import TermsPage from './components/TermsPage';
import Footer from './components/Footer';
import CookieConsent from './components/CookieConsent';
import SchemaMarkup from './components/SchemaMarkup';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('lv');
  const [view, setView] = useState<View>('home');

  useEffect(() => {
    const data = contentData[lang];
    let pageTitle = data.meta.title;
    if (view === 'faq') pageTitle = `${data.faq.title} | Salons Aneri`;
    if (view === 'prices') pageTitle = `${data.prices.title} | Salons Aneri`;
    // gallery case removed
    if (view === 'terms') pageTitle = `${data.terms.title} | Salons Aneri`;
    if (view === 'privacy') pageTitle = `${data.privacy.title} | Salons Aneri`;

    document.title = pageTitle;
    document.documentElement.lang = lang;

    let metaDesc = document.querySelector('meta[name="description"]');
    if (metaDesc) metaDesc.setAttribute('content', data.meta.description);

    let canonical = document.querySelector('link[rel="canonical"]');
    if (!canonical) {
      canonical = document.createElement('link');
      canonical.setAttribute('rel', 'canonical');
      document.head.appendChild(canonical);
    }
    canonical.setAttribute('href', window.location.origin + (view === 'home' ? '' : `/${view}`));

    window.scrollTo(0, 0);
  }, [lang, view]);

  const currentContent = contentData[lang];

  return (
    <div className="min-h-screen bg-stone-50 selection:bg-rose-200">
      <SchemaMarkup content={currentContent} lang={lang} />
      <Header 
        lang={lang} 
        setLang={setLang} 
        content={currentContent} 
        view={view}
        setView={setView}
      />

      <main id="main-content">
        {view === 'home' && (
          <>
            <Hero content={currentContent} />
            <Services content={currentContent} setView={setView} />
            <Advantages content={currentContent} />
          </>
        )}
        {view === 'prices' && <PricePage content={currentContent} setView={setView} />}
        {view === 'faq' && <FAQPage content={currentContent} setView={setView} />}
        {view === 'terms' && <TermsPage title={currentContent.terms.title} content={currentContent.terms.content} setView={setView} homeLabel={currentContent.nav.home} />}
        {view === 'privacy' && <TermsPage title={currentContent.privacy.title} content={currentContent.privacy.content} setView={setView} homeLabel={currentContent.nav.home} />}
      </main>

      <Footer content={currentContent} setView={setView} />
      <CookieConsent content={currentContent} />
    </div>
  );
};

export default App;

