import React, { useState, useEffect } from 'react';
import { Content } from '../types';

interface CookieConsentProps {
  content: Content;
}

const GA_ID = 'G-HTJBX98E4Z';

declare global {
  interface Window {
    dataLayer: any[];
  }
}

const CookieConsent: React.FC<CookieConsentProps> = ({ content }) => {
  const [isVisible, setIsVisible] = useState(false);

  // Helper function to load GA dynamically
  const loadGoogleAnalytics = () => {
    // Avoid double loading
    if (document.getElementById('ga-script')) return;

    const script = document.createElement('script');
    script.id = 'ga-script';
    script.src = `https://www.googletagmanager.com/gtag/js?id=${GA_ID}`;
    script.async = true;
    document.head.appendChild(script);

    window.dataLayer = window.dataLayer || [];
    function gtag(...args: any[]) {
      window.dataLayer.push(args);
    }
    gtag('js', new Date());
    gtag('config', GA_ID);
  };

  useEffect(() => {
    const consent = localStorage.getItem('cookie-consent');

    if (consent === 'true') {
      // If previously accepted, load script immediately
      loadGoogleAnalytics();
      setIsVisible(false);
    } else if (consent === 'false') {
      // If previously denied, do nothing and hide
      setIsVisible(false);
    } else {
      // If no choice made, show banner
      setIsVisible(true);
    }
  }, []);

  const handleAccept = () => {
    localStorage.setItem('cookie-consent', 'true');
    loadGoogleAnalytics();
    setIsVisible(false);
  };

  const handleDecline = () => {
    localStorage.setItem('cookie-consent', 'false');
    setIsVisible(false);
  };

  if (!isVisible) return null;

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-rose-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] p-4 md:p-6 z-[150] flex flex-col md:flex-row items-center justify-between gap-4 animate-in slide-in-from-bottom duration-500">
      <div className="text-slate-700 text-sm md:text-base text-center md:text-left">
        {content.cookie.text}
      </div>
      <div className="flex gap-4">
        <button
          onClick={handleDecline}
          className="bg-transparent border border-slate-300 hover:bg-slate-100 text-slate-600 px-6 py-2 rounded-lg font-medium transition-colors whitespace-nowrap"
        >
          {content.cookie.declineBtn}
        </button>
        <button
          onClick={handleAccept}
          className="bg-primary hover:bg-rose-800 text-white px-8 py-2 rounded-lg font-medium transition-colors whitespace-nowrap shadow-md"
        >
          {content.cookie.acceptBtn}
        </button>
      </div>
    </div>
  );
};

export default CookieConsent;
